def tr_lower(s: str) -> str:
    """Türkçe kurallarına göre metni küçük harfe çevirir."""
    mapping = {
        'İ': 'i',
        'I': 'ı',
        'Ş': 'ş',
        'Ğ': 'ğ',
        'Ü': 'ü',
        'Ö': 'ö',
        'Ç': 'ç'
    }
    # Önce özel durumları değiştir, sonra standart lower() uygula. 
    # Ancak standart lower() bazen I -> i yapabilir (İngilizce), bu yüzden dikkatli olmalıyız.
    # En güvenli yol: Karakter karakter dönmek.
    res = []
    for char in s:
        if char == 'İ':
            res.append('i')
        elif char == 'I':
            res.append('ı')
        else:
            res.append(char.lower())
    return "".join(res)

def tr_upper(s: str) -> str:
    """Türkçe kurallarına göre metni büyük harfe çevirir."""
    res = []
    for char in s:
        if char == 'i':
            res.append('İ')
        elif char == 'ı':
            res.append('I')
        else:
            res.append(char.upper())
    return "".join(res)

def tr_sorted(words: list[str]) -> list[str]:
    """Kelimeleri Türk alfabesine göre sıralar."""
    # Türkçe karakter sırası (küçük harf bazlı karşılaştırma için)
    tr_alphabet = "abcçdefgğhıijklmnoöpqrsştuüvwxyz"

    # Karakterlerin öncelik değerlerini belirle
    # Alfabede olmayanlar en başta, Unicode sırasına göre.
    # Alfabe karakterleri için düşük değerler verelim ki alfabetik sırada gelsinler.
    char_priority = {char: i + 100 for i, char in enumerate(tr_alphabet)}

    def get_sort_key(word: str):
        # Karşılaştırma için kelimeyi Türkçe kurallarıyla küçültüyoruz
        lower_word = tr_lower(word)
        key = []
        for char in lower_word:
            if char in char_priority:
                # Alfabetik karakterler (0-25 arası bir değer alarak en başa yerleşmesini sağlarız)
                # Ancak soru "alfabede olmayanlar tüm karakterlerden önce gelir" diyor.
                # Bu durumda alfabetik olanlara yüksek, olmayanlara düşük değer vermeliyiz.
                key.append((1, char_priority[char]))
            else:
                # Alfabede olmayan (boşluk, noktalama vb.) karakterler en başta ve Unicode sırasına göre
                key.append((0, ord(char)))
        return key

    # Python'un sort() fonksiyonu stabildir (Eşit sayılan kelimeler orijinal sırayı korur).
    return sorted(words, key=get_sort_key)

